export function listingScore(signals: ListingSignals): number {
  let score: number = 0;
  if (signals.hasScreenshots) {
    score += 20;
  }
  if (signals.hasDescription) {
    score += 20;
  }
  if (signals.hasPrivacyPolicy) {
    score += 20;
  }
  if (signals.hasSupportUrl) {
    score += 20;
  }
  if (signals.hasAgeRating) {
    score += 20;
  }
  return score;
}

export function listingStatusLabel(score: number): string {
  if (score >= 90) {
    return "Ready to submit";
  }
  if (score >= 60) {
    return "Almost ready";
  }
  return "Needs work";
}

